create extension if not exists pgcrypto;
create type public.gpcc_role as enum ('Administrator','Editor','Member');
create type public.account_status as enum ('Pending','Approved','Rejected','Inactive');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text default '',role public.gpcc_role not null default 'Member',status public.account_status not null default 'Pending',created_at timestamptz default now());
create table public.income(id uuid primary key default gen_random_uuid(),date date not null,contributor text not null,flat_no text,amount numeric(14,2) not null check(amount>0),mode text not null check(mode in('Cash','Cheque','Online')),reference text,status text default 'Cleared',created_by uuid references auth.users(id),created_at timestamptz default now(),deleted_at timestamptz);
create table public.expenses(id uuid primary key default gen_random_uuid(),date date not null,requisition_no text not null,vendor text not null,bill_no text,bill_date date,category text,gross_amount numeric(14,2) not null check(gross_amount>0),tds_rate numeric(5,2) default 0,source text,mode text,payment_date date,payment_reference text,document_url text,created_by uuid references auth.users(id),created_at timestamptz default now(),deleted_at timestamptz);
create table public.fund_transfers(id uuid primary key default gen_random_uuid(),date date not null,direction text not null,amount numeric(14,2) not null check(amount>0),requisition_no text,remarks text,created_by uuid references auth.users(id),created_at timestamptz default now());
create table public.tds_payments(id uuid primary key default gen_random_uuid(),date date not null,amount numeric(14,2) not null check(amount>0),challan_no text,created_at timestamptz default now());
create table public.audit_logs(id bigint generated always as identity primary key,occurred_at timestamptz default now(),actor_id uuid references auth.users(id),action text not null,entity_type text not null,entity_id text,old_data jsonb,new_data jsonb);
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$begin insert into public.profiles(id,role,status) values(new.id,'Member','Pending');return new;end;$$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
alter table public.profiles enable row level security;alter table public.income enable row level security;alter table public.expenses enable row level security;alter table public.fund_transfers enable row level security;alter table public.tds_payments enable row level security;alter table public.audit_logs enable row level security;
create or replace function public.current_role() returns public.gpcc_role language sql stable security definer set search_path=public as $$select role from public.profiles where id=auth.uid() and status='Approved'$$;
create policy "profile read" on public.profiles for select using(id=auth.uid() or public.current_role()='Administrator');
create policy "income read" on public.income for select using(public.current_role() is not null);create policy "income edit" on public.income for all using(public.current_role() in('Administrator','Editor')) with check(public.current_role() in('Administrator','Editor'));
create policy "expense read" on public.expenses for select using(public.current_role() is not null);create policy "expense edit" on public.expenses for all using(public.current_role() in('Administrator','Editor')) with check(public.current_role() in('Administrator','Editor'));
create policy "transfer read" on public.fund_transfers for select using(public.current_role() is not null);create policy "transfer edit" on public.fund_transfers for all using(public.current_role() in('Administrator','Editor')) with check(public.current_role() in('Administrator','Editor'));
create policy "audit read" on public.audit_logs for select using(public.current_role()='Administrator');
